(* [comment removed for export] *)
Definition z4s32_D5_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x28 x29 x31 : word)
         (SPF DT4 DBL DBH DST dcap tl P B CZ : Z) (cells : list deltX2) (obuf : list Z),
    z4s1_dctx RNG mm SPF DT4 DBL DBH DST dcap tl -> mem_inv asegs mm ->
    x2_table_ok cells tl -> bytes_at asegs mm DT4 (firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells)) ->
    u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
    rw_cells asegs mm (SPF + 312) [C8 (Z_to_bv 64 DT4)] -> 0 <= CZ < 2^64 ->
    DST <= P -> P + 10 <= DST + dcap -> 0 <= B <= 7 ->
    (forall (mm' : amem) (BZ PZ : Z) (k5 k7 k11 k16 k17 k31 : word),
       munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       (exists obuf' : list Z, u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
       0 <= BZ <= 67 -> P + 5 <= PZ <= P + 10 ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 BZ) (Z_to_bv 64 SPF) gp tp k5 (Z_to_bv 64 CZ) k7 x8 x9 x10 k11 x12 x13 x14
                                 (Z_to_bv 64 PZ) k16 k17 x18 x19 x20 x21 x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) x28 x29
                                 (Z_to_bv 64 (64 - tl)) k31)
                            F (Z_to_bv 64 0x8abe8) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR (Z_to_bv 64 B) (Z_to_bv 64 SPF) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 P)
                             (Z_to_bv 64 CZ) x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) x28 x29
                             (Z_to_bv 64 (64 - tl)) x31)
                        F (Z_to_bv 64 0x8a914) fc None mm (seg_rom asegs)).

